export function puffinRoomArt(scene, dk = dayKey()){
  return scene === "pi_warden" ? wardenRoom(dk) : scene === "pi_lamp" ? lampRoom() : scene === "pi_kitchen" ? kitchenRoom() : scene === "pi_studio" ? studioRoom() : tearoomRoom();
}
